# Compute exact numeric productivity norm, engineering first-principles, and 8-hour shift logic for all Table 5E records
for r in TABLE_5E_RECORDS:
    rc = r.get('res_code', '')
    name = r.get('res_name', '')
    scope = r.get('scope', '')
    task = r.get('task_spec', '')
    strata = r.get('strata', '')
    method = r.get('method', '')
    b_qty = r.get('batch_qty', 100)
    b_unit = r.get('batch_unit', 'sqm')
    qty_c = r.get('qty_coeff', 0)
    u = r.get('res_unit', '')
    el = r.get('engineering_logic', '')

    if u == 'day' and qty_c > 0:
        r['productivity_val'] = b_qty / qty_c
    else:
        r['productivity_val'] = None

    fp = r.get('first_principles')
    sl = r.get('shift_logic')

    if not fp:
        if "Surface Excavation" in scope:
            if rc == "0114":
                fp = "Manual pickaxe and phowrah loosening of hard dry soil crust up to 30 cm depth, spade trimming to formation level, and clod pulverization."
            elif rc == "0115":
                fp = "Manual tagari/basket loading with shovel, haulage within 50 m lead, and tipping onto spoil banks (lift ≤1.5 m)."
        elif "Embankment" in scope:
            if rc == "0114":
                if "banking only" in task.lower() or "excavation excluded" in task.lower():
                    fp = "Pulverizing clods, leveling dumped earth into 20 cm loose layers and shaping embankment slope profiles."
                else:
                    fp = "Rough soil digging, heavy clod breaking, spreading in 20 cm layers and dressing embankment side slopes."
            elif rc == "0115":
                fp = "Basket haulage within 50 m lead, tipping and uniform spreading in layers not exceeding 20 cm depth."
            elif rc == "0101":
                if "DEDUCT" in task or qty_c < 0:
                    fp = "Omission of OMC compaction watering: eliminates water cartage and mashak spraying allowance."
                else:
                    fp = "Spraying water over loose 20 cm layers from leather mashak or hose to reach Optimum Moisture Content (OMC) prior to rolling."
            elif rc in ("0003", "0011", "0113"):
                if "DEDUCT" in task or qty_c < 0:
                    fp = "Omission of power rolling: eliminates 8-10t 3-wheel diesel roller consolidation."
                elif rc == "0003":
                    fp = "8-10 tonne diesel 3-wheel power roller conducting 6-8 passes on 20 cm loose layers for roadbed embankment."
                elif "chowkidar" in name.lower() or rc == "0011":
                    fp = "Road roller attendant / chowkidar: monitoring compaction passes, edge guidance and equipment safety."
                elif rc == "0113":
                    fp = "Sundries for roller: lubricants, cotton waste, water spray attendance and small implements."
            elif rc == "9999":
                fp = "Sundries: maintenance of digging tools, pickaxe sharpening, wicker baskets and profile templates."
        
        if not fp:
            if rc == "0114":
                fp = f"Manual excavation, trimming of slopes/beds, and clod breaking in {strata.lower()}."
            elif rc == "0115":
                fp = f"Manual spoil handling, basket loading and haulage within 50m lead / 1.5m lift in {strata.lower()}."
            elif rc == "0101":
                fp = f"Water spraying for soil conditioning, dampening trench bottoms or compaction moistening."
            elif rc == "0128":
                fp = "Gang supervision, alignment checking, depth peg verification and safety monitoring."
            elif rc in ("0020", "0034"):
                fp = f"Mechanical excavation using 0.9 cum hydraulic bucket shovel in {strata.lower()}."
            elif rc == "0017":
                fp = "Hydraulic tipper transport of excavated earth/rock to designated dumping grounds."
            elif rc in ("0132", "0133", "0134", "0135"):
                fp = f"Rock cutting / pneumatic rock breaking / hole drilling in {strata.lower()}."
            elif rc in ("1197", "1198", "0302", "0112"):
                fp = "Timber shuttering/shoring: poling boards, walling and strutting for trench safety."
            elif "7022" in rc or "chemical" in name.lower():
                fp = "Chemical emulsion application for continuous subterranean anti-termite barrier."
            elif rc == "9999":
                fp = "Tools, tackles, sharpening, profile templates, and operational consumable sundries."
            else:
                fp = f"Specialized operational execution for {task} ({name})."

    if not sl:
        if "Surface Excavation" in scope:
            if rc == "0114":
                sl = f"Gang: 4 Beldars × 13.60 h = 54.40 man-hrs ÷ 8.00 h = 6.800 Beldar-days per {b_qty} {b_unit}. Daily productivity norm P = 14.71 {b_unit}/8-hr shift (SE = 0.544 hr/{b_unit}, pace = 32.6 min/{b_unit})."
            elif rc == "0115":
                sl = f"Gang: 4 Coolies × 11.20 h = 44.80 man-hrs ÷ 8.00 h = 5.600 Coolie-days per {b_qty} {b_unit}. Daily productivity norm P = 17.86 {b_unit}/8-hr shift (SE = 0.448 hr/{b_unit}, pace = 26.9 min/{b_unit})."
        elif "Embankment" in scope:
            if rc == "0114":
                if "banking only" in task.lower() or "excavation excluded" in task.lower():
                    sl = f"Gang: 2 Beldars × 8.80 h = 17.60 man-hrs ÷ 8.00 h = 2.200 Beldar-days per {b_qty} {b_unit}. Daily output P = 4.55 {b_unit}/8-hr shift (SE = 1.76 hr/{b_unit})."
                else:
                    sl = f"Gang: 4 Beldars × 11.80 h = 47.20 man-hrs ÷ 8.00 h = 5.900 Beldar-days per {b_qty} {b_unit}. Daily output P = 1.695 {b_unit}/8-hr shift (SE = 4.72 hr/{b_unit})."
            elif rc == "0115":
                sl = f"Gang: 3 Coolies × 9.60 h = 28.80 man-hrs ÷ 8.00 h = 3.600 Coolie-days per {b_qty} {b_unit}. Daily output P = 2.778 {b_unit}/8-hr shift (SE = 2.88 hr/{b_unit})."
            elif rc == "0101":
                if "DEDUCT" in task or qty_c < 0:
                    sl = "Reverses the OMC compaction watering allowance: -0.400 bhishti-day per 10 cum."
                else:
                    sl = f"Gang: 1 Bhishti × 3.20 h = 3.20 man-hrs ÷ 8.00 h = 0.400 Bhishti-day per {b_qty} {b_unit}. Daily output P = 25.00 {b_unit}/8-hr shift (SE = 0.32 hr/{b_unit})."
            elif rc == "0003":
                if "DEDUCT" in task or qty_c < 0:
                    sl = "Reverses the power rolling allowance: -0.008 roller-day per 10 cum."
                else:
                    sl = f"Plant: 1 Roller × 0.064 h (3.84 min) ÷ 8.00 h = 0.008 roller-day per {b_qty} {b_unit}. Output P = 1,250 {b_unit}/8-hr shift."
            elif "chowkidar" in name.lower() or rc == "0011":
                sl = f"Crew: 1 Chowkidar × 0.064 h ÷ 8.00 h = 0.008 man-day per {b_qty} {b_unit} matching roller operating hours."
            elif rc == "0113":
                sl = f"Operational allowance per {b_qty} {b_unit} matching CPWD DAR benchmark."
            elif rc == "9999":
                sl = f"Lump sum tools & plant consumable allowance per standard batch of {b_qty} {b_unit}."
        
        if not sl:
            if el and "÷ 8" in el:
                sl = el
            elif u == 'day' and qty_c > 0:
                prod = b_qty / qty_c
                se = (qty_c * 8.0) / b_qty
                sl = f"Shift allocation: {qty_c:.3f} {name}-days per {b_qty} {b_unit} (Daily norm P = {prod:.2f} {b_unit}/8-hr shift, SE = {se:.4f} hr/{b_unit})."
            elif u == 'day' and qty_c < 0:
                sl = f"Deduction rate factor: {qty_c:.3f} {name}-days per {b_qty} {b_unit}."
            elif el:
                sl = el
            else:
                sl = f"CPWD standard batch norm: {qty_c} {u} per {b_qty} {b_unit} ({r.get('item_code', '')})."

    r['first_principles'] = fp
    r['shift_logic'] = sl

# Enrich MASTER_ACTIVITIES and TABLE_5E_RECORDS with Category & Task keys
_CODE_TO_CAT_TASK = {code: (cat, task) for cat, task, code in HEADING_TASK_CATALOG}
_PIPE_CODES = {'2.10.1.1', '2.10.1.2', '2.10.1.3', '2.11', '2.12', '2.13.1.1'}

for act in MASTER_ACTIVITIES:
    code = act.get('item_code', '')
    if act.get('scope') == 'Foundation & Pipeline Trenching':
        if code in _PIPE_CODES or 'pipe' in act.get('task_spec', '').lower() or 'cable' in act.get('task_spec', '').lower():
            act['scope'] = 'Pipeline & Cable Trenching (narrow trenches with sockets & refilling)'
        else:
            act['scope'] = 'Foundation & Bulk Trenches (>30cm depth, >1.5m width or >10 sqm plan)'
            
    if 'Extra depth' in act.get('method', ''):
        act['method'] = 'Manual labor (depth ≤1.5m)'
        
    if code == '2.8.1':
        act['method'] = 'Mechanical (Hydraulic Excavator 0.9 cum)'

    if code == '2.4':
        act['published_say'] = 4.30
    elif code == '2.5':
        act['published_say'] = 33.00

    if code in _CODE_TO_CAT_TASK:
        cat, task = _CODE_TO_CAT_TASK[code]
        act['category'] = cat
        act['task_spec'] = task
        act['cat_task_key'] = f"{cat}|{task}"
    else:
        act['category'] = act.get('scope', '')
        act['cat_task_key'] = f"{act['scope']}|{act['task_spec']}"
    act['full_key'] = f"{act['scope']}|{act['strata']}|{act['method']}|{act['task_spec']}"

